def place(item, bins, capacity):
    # Best Fit, but avoid creating very small unusable remainders when
    # another reasonably usable remainder is available.
    limit = min(item // 2, capacity // 7)
    best_index = -1
    best_key = None

    for i, remaining in enumerate(bins):
        if remaining < item:
            continue

        leftover = remaining - item
        is_fragment = 0 < leftover < limit
        key = (is_fragment, leftover)

        if best_key is None or key < best_key:
            best_key = key
            best_index = i

    return best_index if best_index >= 0 else len(bins)

def place(item, bins, capacity):
    # Hybrid online rule:
    #  - Large items (>= 1/4 of capacity): Best Fit, packing them as tightly
    #    as possible so they don't fragment the open bins.
    #  - Small items (< 1/4 of capacity): Worst Fit among feasible bins,
    #    keeping nearly-full bins (and their tight residuals) intact for
    #    future large items; this avoids sealing small unusable gaps early.
    # Exact fits always win.
    best_index = -1
    best_leftover = None
    worst_index = -1
    worst_remaining = -1

    small = 4 * item <= capacity

    for i, remaining in enumerate(bins):
        if remaining < item:
            continue
        if remaining == item:
            return i
        if small:
            if remaining > worst_remaining:
                worst_remaining = remaining
                worst_index = i
        else:
            leftover = remaining - item
            if best_leftover is None or leftover < best_leftover:
                best_leftover = leftover
                best_index = i

    if small:
        return worst_index if worst_index >= 0 else len(bins)
    return best_index if best_index >= 0 else len(bins)

def place(item, bins, capacity):
    # Space-aware hybrid online rule:
    #  - Exact fits are always taken immediately.
    #  - Large items (>= 1/4 of capacity): Best Fit, so they are packed
    #    tightly and do not fragment open bins.
    #  - Small items (< 1/4 of capacity): prefer a bin where, after
    #    placement, the residual is still >= 1/4 of capacity (i.e. remains
    #    "usable" by future large items); among such bins use Best Fit.
    #    If no such bin exists, use Worst Fit so the resulting dead gap is
    #    as large as possible (large gaps are more likely fillable later).
    quarter = capacity / 4
    small = item < quarter

    best_index = -1
    best_leftover = None
    usable_index = -1
    usable_leftover = None
    worst_index = -1
    worst_remaining = -1

    for i, remaining in enumerate(bins):
        if remaining < item:
            continue
        if remaining == item:
            return i
        leftover = remaining - item
        if not small:
            if best_leftover is None or leftover < best_leftover:
                best_leftover = leftover
                best_index = i
        else:
            if leftover >= quarter:
                if usable_leftover is None or leftover < usable_leftover:
                    usable_leftover = leftover
                    usable_index = i
            else:
                if remaining > worst_remaining:
                    worst_remaining = remaining
                    worst_index = i

    if not small:
        return best_index if best_index >= 0 else len(bins)
    if usable_index >= 0:
        return usable_index
    return worst_index if worst_index >= 0 else len(bins)
